def parse_csv_line(line):
    fields = []
    i = 0
    while True:
        if line.startswith('"', i):
            i += 1                                       # skip the opening quote
            pieces = []
            while True:
                j = line.find('"', i)
                if j == -1:
                    raise ValueError("unterminated quoted field")
                pieces.append(line[i:j])
                if line.startswith('"', j + 1):          # "" is one literal quote: keep reading
                    pieces.append('"')
                    i = j + 2
                else:
                    i = j + 1                            # the closing quote
                    break
            fields.append("".join(pieces))
            if i < len(line) and line[i] != ",":
                raise ValueError("unexpected text after a closing quote")
        else:
            j = line.find(",", i)
            if j == -1:
                j = len(line)
            fields.append(line[i:j])
            i = j
        if i >= len(line):
            return fields
        i += 1                                           # step over the comma: one more field follows, maybe empty
